(1196085, 148247, 30850, '<td valign="top">Very moving shot</td>', 'Very moving shot', '2005-02-26 19:31:38.000000', NULL, 1),
(1196095, 148384, 2798, '<td valign="top">Looks like it might be quite a nice go set, though I can''t see evidence of clam shell stripes on the white stones. Nice idea for a shot but I don''t think I would have set up the board in such an implausable position. Also relies heavily on the viewer''s understanding of the rules of go. I think your lighting might have made the white stones lighter to help the viewer distinguish the two colours more readily. I like the shallow depth of field and the B&amp;W. 7</td>', 'Looks like it might be quite a nice go set, though I can''t see evidence of clam shell stripes on the white stones. Nice idea for a shot but I don''t think I would have set up the board in such an implausable position. Also relies heavily on the viewer''s understanding of the rules of go. I think your lighting might have made the white stones lighter to help the viewer distinguish the two colours more readily. I like the shallow depth of field and the B&W. 7', '2005-02-26 19:48:02.000000', NULL, 1),
(1196104, 148850, 34298, '<td valign="top">perfect idea</td>', 'perfect idea', '2005-02-26 20:02:50.000000', NULL, 1),
