(1197369, 147755, 23458, '<td valign="top">Now this is an amazing shot. Into my favourites it goes.</td>', 'Now this is an amazing shot. Into my favourites it goes.', '2005-02-28 00:16:51.000000', NULL, 0),
(1197370, 147782, 25232, '<td valign="top">Bella, I think this would have done better if the image had more tonal range. I know that is not always easy to capture with snow on the ground, but we expect a dog''s nose to be darker. Your unplugged was high key and also lacked a full tonal range, but with that picture it looked intended and it worked well. Great photo anyway.</td>', 'Bella, I think this would have done better if the image had more tonal range. I know that is not always easy to capture with snow on the ground, but we expect a dog''s nose to be darker. Your unplugged was high key and also lacked a full tonal range, but with that picture it looked intended and it worked well. Great photo anyway.', '2005-02-28 00:16:56.000000', NULL, 0),
(1197371, 148660, 22734, '<td valign="top">A capture that visits a historical site to bring a nice slice to DPC. Impressive. Congratulations on your yellow.</td>', 'A capture that visits a historical site to bring a nice slice to DPC. Impressive. Congratulations on your yellow.', '2005-02-28 00:16:57.000000', NULL, 0),
(1197372, 148189, 5286, '<td valign="top">This should have finished much much higher. Once again, congratulations on producing a simply beautiful image, so neat.</td>', 'This should have finished much much higher. Once again, congratulations on producing a simply beautiful image, so neat.', '2005-02-28 00:17:03.000000', NULL, 0);
